    public static boolean isCryptoInstrument(JsonNode item) { try { normalizeInstrument(item, "instrument"); return true; } catch (RuntimeException ignored) { return false; } }

    public static ArrayNode validateCryptoUniverse(JsonNode value) { return validateCryptoUniverse(value, false); }

    public static ArrayNode validateCryptoUniverse(JsonNode value, boolean candidate) {
        object(value, candidate ? "candidate" : "tradable_instrument_contract"); JsonNode listNode = firstTruthy(value, "instruments", "allowed_instruments", "tradable", "contracts"); List<JsonNode> instruments = new ArrayList<>(rows(listNode));
        if (instruments.isEmpty() && (bool(value.get("instrument_type")) || bool(value.get("type")))) instruments.add(value);
        for (JsonNode asset : rows(value.get("assets"))) {
            if (!asset.isTextual()) instruments.add(asset);
            else instruments.add(JSON.objectNode().put("asset", text(asset)).put("asset_class", "crypto").put("instrument_type", optionText(value, "instrument_type", optionText(value, "type", "spot"))).put("venue", optionText(value, "venue", "declared")).put("collateral", optionText(value, "collateral", "spot")).put("funding_contract", optionText(value, "funding_contract", "not_applicable")));
        }
        if (instruments.isEmpty()) throw new IllegalArgumentException((candidate ? "candidate" : "tradable_instrument_contract") + " must declare at least one crypto instrument");
        ArrayNode normalized = JSON.arrayNode(); for (int index = 0; index < instruments.size(); index++) {
            JsonNode raw = instruments.get(index); if (raw.isTextual()) raw = JSON.objectNode().put("asset", text(raw)).put("asset_class", "crypto").put("instrument_type", optionText(value, "instrument_type", optionText(value, "type", "spot"))).set("venue", cloneNode(value.get("venue")));
            if (raw.isObject() && !raw.has("funding_contract") && bool(value.get("funding_contract"))) ((ObjectNode) raw).set("funding_contract", cloneNode(value.get("funding_contract")));
            normalized.add(normalizeInstrument(raw, (candidate ? "candidate" : "tradable_instrument_contract") + ".instruments[" + index + "]"));
        }
        return normalized;
    }

    private static ObjectNode normalizeInstrument(JsonNode item, String name) {
        ObjectNode input = objectCopy(item, name); String type = lower(firstTruthy(input, "instrument_type", "type", "expression_type")); String cls = lower(firstTruthy(input, "asset_class", "assetClass")); String asset = lower(firstTruthy(input, "asset", "symbol"));
        if (asset.isEmpty()) throw new IllegalArgumentException(name + ".asset is required"); if (!cls.isEmpty() && NON_CRYPTO_ASSET_CLASSES.contains(cls)) throw new IllegalArgumentException(name + " is non-crypto and cannot be tradable"); if (!cls.isEmpty() && !CRYPTO_ASSET_CLASSES.contains(cls)) throw new IllegalArgumentException(name + ".asset_class must be crypto for a tradable instrument"); if (!CRYPTO_INSTRUMENT_TYPES.contains(type)) throw new IllegalArgumentException(name + ".instrument_type must be a crypto spot or derivative type");
        boolean derivative = !"spot".equals(type); if (derivative) { if (!bool(firstTruthy(input, "venue", "exchange"))) throw new IllegalArgumentException(name + ".venue is required for crypto derivatives"); if (!bool(firstTruthy(input, "collateral", "collateral_asset"))) throw new IllegalArgumentException(name + ".collateral is required for crypto derivatives"); if (Set.of("perpetual", "perp", "basis", "funding", "carry", "derivative").contains(type) && !input.has("funding_contract") && !input.has("carry_contract") && !input.has("funding") && !input.has("carry")) throw new IllegalArgumentException(name + " must declare funding/carry metadata"); }
        input.put("asset", asset).put("asset_class", "crypto").put("instrument_type", type).put("derivative", derivative); return input;
    }

