        JsonNode horizon = firstFrom(premise, List.of("holding_horizon", "horizon")); range(horizon, "precommit.holding_horizon", 0, Double.POSITIVE_INFINITY); if (!bool(horizon.get("unit"))) throw new IllegalArgumentException("precommit.holding_horizon.unit is required");
