        range(requiredAlias(value, premise, List.of("expected_win_rate", "win_rate_range"), "expected_win_rate"), "precommit.expected_win_rate", 0, 1);
        JsonNode payoff = firstFrom(premise, List.of("expected_payoff", "payoff", "average_win_loss")); object(payoff, "precommit.payoff"); JsonNode win = firstFrom(payoff, List.of("average_win_r", "average_win_r_range", "win_r")), loss = firstFrom(payoff, List.of("average_loss_r", "average_loss_r_range", "loss_r")); if (win == null || loss == null) throw new IllegalArgumentException("precommit.payoff must declare average win and loss in R"); if (!bool(firstTruthy(payoff, "qualitative_shape", "shape"))) throw new IllegalArgumentException("precommit.payoff.qualitative_shape is required"); range(win, "precommit.payoff.average_win_r", 0, Double.POSITIVE_INFINITY); range(loss, "precommit.payoff.average_loss_r", Double.NEGATIVE_INFINITY, Double.POSITIVE_INFINITY);
