        if (!"COMPOSITE_SCORE".equals(stage) && hasForbiddenScoreKey(value)) throw new IllegalArgumentException("composite score/thresholds are forbidden before COMPOSITE_SCORE (stage " + stage + ")"); if ("COMPOSITE_SCORE".equals(stage) && !bool(value.get("score_free_baseline_sha256"))) throw new IllegalArgumentException("COMPOSITE_SCORE requires score_free_baseline_sha256");
