    public static ObjectNode runStressSuite(JsonNode tradesNode, JsonNode suite) {
        validateStressSuite(suite); List<JsonNode> source = rows(tradesNode); ArrayNode results = JSON.arrayNode(); JsonNode scenarios = bool(suite.get("required_scenarios")) ? suite.get("required_scenarios") : suite.get("scenarios");
        for (JsonNode item : rows(scenarios)) { String id = canonicalStressId(optionText(item, "id", text(item.get("name")))); List<StressRow> stressed = new ArrayList<>(); for (JsonNode trade : source) { JsonNode valueNode = firstDefined(trade, "net_r", "return_r", "r"); if (finite(valueNode)) stressed.add(new StressRow(trade, jsNumber(valueNode))); } List<String> missing = new ArrayList<>();
            if ("fee_slippage".equals(id)) stressed = transform(stressed, row -> { if (!finite(row.trade.get("fee_r")) || !finite(row.trade.get("slippage_r"))) { missing.add(tradeId(row.trade)); return null; } return new StressRow(row.trade, row.value - (Math.abs(jsNumber(row.trade.get("fee_r"))) + Math.abs(jsNumber(row.trade.get("slippage_r")))) * (jsNumber(item.get("multiplier")) - 1)); });
            if ("funding_carry".equals(id)) stressed = transform(stressed, row -> { if (!finite(row.trade.get("funding_debit_r"))) { missing.add(tradeId(row.trade)); return null; } return new StressRow(row.trade, row.value - Math.abs(jsNumber(row.trade.get("funding_debit_r"))) * (jsNumber(item.get("multiplier")) - 1)); });
            if ("adverse_execution_gap".equals(id)) stressed = stressed.stream().map(row -> new StressRow(row.trade, row.value - jsNumber(item.get("debit_r")))).toList();
            if ("liquidity_capacity".equals(id)) stressed = stressed.stream().filter(row -> { double notional = jsNumber(row.trade.get("notional")), volume = jsNumber(row.trade.get("available_liquidity_notional")); if (!(notional >= 0) || !(volume > 0)) { missing.add(tradeId(row.trade)); return false; } return notional / volume <= jsNumber(item.get("maximum_participation_rate")); }).toList();
            if ("venue_outage_blackout".equals(id)) stressed = stressed.stream().filter(row -> { long time = jsDate(firstTruthy(row.trade, "entry_time", "signal_time")); String venue = lower(firstTruthy(row.trade, "venue")); if (venue.isEmpty()) venue = lower(row.trade.path("instrument").get("venue")); if (time == Long.MIN_VALUE || venue.isEmpty()) { missing.add(tradeId(row.trade)); return false; } final long at = time; final String place = venue; return rows(item.get("windows")).stream().noneMatch(window -> place.equals(lower(window.get("venue"))) && at >= jsDate(window.get("start")) && at < jsDate(window.get("end"))); }).toList();
            List<Double> values = stressed.stream().map(StressRow::value).toList(); Double expectancy = values.isEmpty() ? null : jsMean(values); List<String> missingIds = missing.stream().distinct().sorted().toList(); boolean pass = missingIds.isEmpty() && values.size() >= jsNumber(item.get("minimum_observations")) && expectancy != null && expectancy >= jsNumber(item.get("minimum_expectancy_r")); ObjectNode result = JSON.objectNode().put("id", id); putDoubleOrNull(result, "expectancy_r", expectancy); result.put("observations", values.size()).set("missing_model_inputs", strings(missingIds)); ArrayNode scopes = result.putArray("missing_model_input_scopes"); for (String tradeId : missingIds) { JsonNode trade = source.stream().filter(row -> tradeId(row).equals(tradeId)).findFirst().orElse(null); ObjectNode scope = JSON.objectNode().put("trade_id", tradeId); putNullable(scope, "candidate_id", trade == null ? null : trade.get("candidate_id")); putNullable(scope, "asset", trade == null ? null : trade.get("asset")); scopes.add(scope); } result.put("pass", pass).put("modeled", "declared deterministic cost debit/capacity rejection/venue-time blackout; no order-book simulation"); results.add(result); }
        ObjectNode out = JSON.objectNode().put("suite_sha256", hash(suite)); out.set("scenarios", results); out.put("pass", rows(results).stream().allMatch(row -> row.path("pass").asBoolean(false))).put("assumptions", "Net R must already include base costs. Stress adds only declared incremental cost debits and deterministic capacity/outage exclusions; no order-book simulation."); return out;
    }

