            if (selected == null) { ObjectNode missing = JSON.objectNode().put("asset", asset).put("status", "REJECTED").putNull("candidate_id"); missing.set("reasons", strings(List.of("MISSING_ASSET_METRICS"))); perAsset.add(missing); continue; }
            ObjectNode plateau;
