                ObjectNode selection = JSON.objectNode(); selection.set("experiment", cloneNode(experiment)); selection.set("diagnostics", plateauDiagnostics(diagOptions)); selection.set("candidate_id", cloneNode(selected.get("candidate_id"))); plateau = validatePlateauSelection(selection);
